46	    itemsByOutfit.set(p.outfit_id, list);
47	  }
48	
49	  const wearsById: Record<string, number> = {};
50	  const lastWornById: Record<string, string> = {};
51	  for (const w of wears) {
52	    for (const itemId of itemsByOutfit.get(w.outfit_id) ?? []) {
53	      wearsById[itemId] = (wearsById[itemId] ?? 0) + 1;
54	      if (!lastWornById[itemId] || w.worn_on > lastWornById[itemId]) {
55	        lastWornById[itemId] = w.worn_on;
56	      }
57	    }
58	  }
59	
60	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
61	  const byId = new Map(items.map((i) => [i.id, i]));
62	  const nameOf = (id: string) => byId.get(id)?.name ?? "That piece";
63	
64	  const stats = closetStats(items, wears.flatMap((w) => (itemsByOutfit.get(w.outfit_id) ?? []).map((item_id) => ({ item_id }))));
65	  const entitlements = entitlementsFor(profile?.tier);
66	
67	  const closet: CandidateItem[] = items.map((i) => ({
68	    id: i.id,
69	    category: i.category,
70	    colors: i.colors ?? [],
71	    formality: i.formality,
72	    seasons: i.seasons ?? [],
73	    material: i.material,
74	    texture: i.texture,
75	    pattern: i.pattern,
76	  }));
77	  // Skipped entirely for a user who cannot see it — a few dozen passes over the
78	  // closet is cheap, but computing an answer nobody is shown is still waste.
79	  const gap = entitlements.gapAnalysis ? biggestGap(closet, ALL_OCCASIONS) : null;
80	
81	  return (
82	    <div className="flex min-h-dvh flex-1 flex-col">
83	      <StatsView
84	        value={stats.value}
85	        // Wears are logged against an OUTFIT, so the headline is the number of
86	        // logged outfits — not the sum of per-item attributions, which counts a
87	        // five-piece look five times.
88	        totalWears={wears.length}
89	        avgCostPerWear={stats.avgCostPerWear}
90	        mostWorn={mostWorn(items, wearsById, TOP_N).map((id) => ({
91	          id,
92	          name: nameOf(id),
93	          sub: `Worn ${wearsById[id]} times`,
94	        }))}
95	        dust={gatheringDust(items, lastWornById, today, TOP_N).map((d) => ({
96	          id: d.id,
97	          name: nameOf(d.id),
98	          days: d.days,
99	        }))}
100	        gap={
101	          gap && {
102	            label: gap.candidate.label,
103	            unlocks: gap.unlocks,
104	            reason: `It pairs with more of your closet than anything else you're missing.`,
105	          }
106	        }
107	        entitlements={{
108	          analytics: entitlements.analytics,
109	          gapAnalysis: entitlements.gapAnalysis,
110	        }}
111	        isPro={entitlements.tier === "pro"}
112	      />
113	      <MobileNav />
114	    </div>
115	  );
116	}
