16	const LINKS: HubLink[] = [
17	  { href: "/style-dna", label: "Style DNA", desc: "Your archetype, shareable", icon: "dna", ready: false },
18	  { href: "/outfits", label: "Saved Outfits", desc: "Looks you kept", icon: "saved", ready: false },
19	  { href: "/stats", label: "Wear Stats", desc: "What you actually wear", icon: "stats", ready: true },
20	  { href: "/settings", label: "Settings", desc: "Preferences and account", icon: "settings", ready: true },
21	];
