23	export default async function ProfilePage() {
24	  const supabase = await createClient();
25	  const {
26	    data: { user },
27	  } = await supabase.auth.getUser();
28	  if (!user) redirect("/");
29	
30	  const { data: profile } = await supabase
31	    .from("profiles")
32	    .select("display_name, archetype, tier, location_timezone")
33	    .eq("id", user.id)
34	    .single();
35	
36	  /**
37	   * `outfits` counts looks WORN, not looks generated.
38	   *
39	   * The `outfits` table holds every look the generator ever produced — three
40	   * per drop, plus styled looks, plus every past day — so a row count reports
41	   * the generator's output rather than anything the user did, and it inflates
42	   * on its own every day the app runs.
43	   */
44	  const [{ count: pieces }, { data: logs }] = await Promise.all([
45	    supabase.from("items").select("id", { count: "exact", head: true }).eq("archived", false),
46	    supabase.from("wear_logs").select("worn_on").eq("user_id", user.id),
47	  ]);
48	
49	  const today = localDateFor(new Date(), profile?.location_timezone ?? "UTC");
50	  const wornDates = (logs ?? []).map((r) => r.worn_on);
51	
52	  return (
53	    <div className="flex min-h-dvh flex-1 flex-col">
54	      <ProfileHub
55	        name={profile?.display_name ?? "You"}
56	        handle={handleFrom(user.email ?? "")}
57	        initials={initials(profile?.display_name ?? null, user.email ?? "")}
58	        archetype={profile?.archetype ?? null}
59	        palette={paletteFor(profile?.archetype ?? null)}
60	        tier={entitlementsFor(profile?.tier).tier}
61	        stats={{
62	          pieces: pieces ?? 0,
63	          outfits: wornDates.length,
64	          streak: currentStreak(wornDates, today),
65	        }}
66	        links={LINKS}
67	      />
68	      <MobileNav />
69	    </div>
70	  );
71	}
